import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay, EffectCoverflow } from "swiper/modules";
import "swiper/css";
import "swiper/css/effect-coverflow";

const sliderData = [
  { img: "https://tse1.mm.bing.net/th/id/OIP.IcEztEVtRD2CV-HZBY-AvQHaJQ?pid=Api&P=0&h=220", text: "Live Streaming Fun" },
  { img: "", text: "Connect with Friends" },
  { img: "", text: "Earn While You Stream" },
  { img: "", text: "Join Interactive Games" },
  { img: "", text: "Be Part of the Community" },
  { img: "", text: "Win Exciting Rewards" },
  { img: "", text: "Stream Anytime, Anywhere" },
  { img: "", text: "Discover New Talents" },
  { img: "", text: "Host Live Shows" },
  { img: "g", text: "Share Your Moments" },
];

export default function Front() {
  return (
    <section className="z-10 py-10 bg-black">
      <Swiper
        modules={[Autoplay, EffectCoverflow]}
        effect="coverflow"
        grabCursor={true}
        centeredSlides={true}
        slidesPerView={"auto"}
        loop={true}
        autoplay={{ delay: 3000, disableOnInteraction: false }}
        coverflowEffect={{
          rotate: 0,
          stretch: 0,
          depth: 150,
          modifier: 1.5,
          slideShadows: false,
        }}
        className="w-full max-w-[1400px]"
      >
        {sliderData.map((slide, index) => (
          <SwiperSlide
            key={index}
            className="swiper-slide-custom relative"
          >
            <img
              src={slide.img}
              alt={slide.text}
              className="w-full h-full object-cover rounded-3xl"
            />
            <div className="absolute bottom-6 left-6 text-white text-lg font-semibold drop-shadow-lg">
              {slide.text}
            </div>
          </SwiperSlide>
        ))}
      </Swiper>

      <style>{`
        .swiper-slide-custom {
          width: 320px;
          height: 420px;
          transition: transform 0.3s ease;
        }
        .swiper-slide-active {
          width: 480px !important;
          height: 560px !important;
        }
      `}</style>
    </section>
  );
}
